// шаг 3 тикета — getComputedStyle(document.body).direction.
import { test } from '@playwright/test';
import { GUEST_PAGES, ADMIN_PAGES, ADMIN_STATE, pathOf, prepareReadOnly, dismissPopups, waitReady, expectRtlDocument } from './rtl-dir.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('html dir=rtl — живой DOM', () => {
  for (const key of GUEST_PAGES) {
    test(`${key}: <html lang="he" dir="rtl">, body direction rtl #9c4736 @desktop @prod-safe`, async ({ page, context, request }) => {
      const path = await pathOf(request, key);
      await prepareReadOnly(context);
      await dismissPopups(page);
      await page.goto(path);
      await waitReady(page, key);
      await expectRtlDocument(page, path);
    });
  }

  test.describe('admin (#359741)', () => {
    test.use({ storageState: ADMIN_STATE });
    for (const key of ADMIN_PAGES) {
      test(`${key} (admin): <html lang="he" dir="rtl">, body direction rtl #9c4736 #359741 @desktop @prod-safe`, async ({ page, context, request }) => {
        const path = await pathOf(request, key);
        await prepareReadOnly(context);
        await dismissPopups(page);
        await page.goto(path);
        await waitReady(page, key);
        await expectRtlDocument(page, path);
      });
    }
  });
});
